CSS='''*{box-sizing:border-box}body{margin:0;font-family:Inter,Arial,sans-serif;background:#f5f7fa;color:#111827}a{text-decoration:none;color:inherit}.top{height:68px;background:white;border-bottom:1px solid #e4e8ee;display:flex;align-items:center;justify-content:space-between;padding:0 max(18px,calc((100vw - 1120px)/2));position:sticky;top:0;z-index:5}.brand{font-weight:850}.mark{background:#00629b;color:#fff;border-radius:6px;padding:6px 7px;margin-right:8px;font-size:12px}.nav{display:flex;gap:14px;color:#00629b;font-size:13px;font-weight:700}.wrap{width:min(1120px,calc(100% - 30px));margin:auto}.hero{padding:52px 0 28px}.ey{color:#00629b;font-size:11px;letter-spacing:.12em;font-weight:850}.hero h1{font-size:clamp(42px,6vw,66px);line-height:1;margin:8px 0 14px;letter-spacing:-.05em}.blue{color:#00629b}.muted{color:#667085;line-height:1.6}.pills{display:flex;gap:7px;flex-wrap:wrap;margin-top:16px}.pills span{font-size:11px;background:#eef8fd;color:#064b73;border:1px solid #cbe2ef;border-radius:999px;padding:7px 9px}.panel{background:#fff;border:1px solid #e4e8ee;border-radius:18px;box-shadow:0 12px 32px rgba(20,43,68,.06)}.grid{display:grid;grid-template-columns:1fr 310px;gap:20px;padding-bottom:50px}.box{padding:25px}.fg{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field{display:flex;flex-direction:column;gap:6px}.field span{font-size:11px;font-weight:750;color:#4b5869}.field input,.field select,.field textarea{border:1px solid #d4dae2;border-radius:10px;padding:11px}.field textarea{min-height:105px}.field small{font-size:10px;color:#7c8795;line-height:1.4}.wide{grid-column:1/-1}.checks{display:grid;grid-template-columns:1fr 1fr;gap:9px}.check{border:1px solid #e4e8ee;border-radius:11px;padding:11px;font-size:12px}.upload{border:1px dashed #9ebfd2;background:#f7fcff;border-radius:12px;padding:18px;text-align:center}.upload img{max-width:100%;max-height:300px;margin-top:10px;border-radius:10px}.btn{border:0;background:#00629b;color:white;border-radius:10px;padding:11px 14px;font-weight:800;cursor:pointer}.green{background:#137a4d}.red{background:#b42318}.msg{font-size:12px;color:#667085}.ok{color:#137a4d}.bad{color:#b42318}.rules{color:#667085;font-size:12px;line-height:1.65;padding-left:18px}.lr{display:grid;grid-template-columns:22px 1fr auto;gap:7px;padding:8px 0;border-top:1px solid #e4e8ee;font-size:12px}.lr b{color:#00629b}.toolbar{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:12px 14px;margin-bottom:18px}.toolbar select,.toolbar input{border:1px solid #d4dae2;border-radius:9px;padding:9px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;padding-bottom:45px}.card{overflow:hidden}.photo{aspect-ratio:4/3;background:#e9eef2;position:relative}.photo img{width:100%;height:100%;object-fit:cover}.badge{position:absolute;left:10px;bottom:10px;background:#fffE;border-radius:999px;padding:5px 8px;color:#064b73;font-size:10px;font-weight:800}.cb{padding:15px}.cb h2{margin:7px 0;font-size:20px}.meta,.foot{display:flex;justify-content:space-between;font-size:10px;color:#7d8795}.foot{border-top:1px solid #e4e8ee;margin-top:11px;padding-top:10px}.pts{color:#137a4d;font-weight:800}.loc{font-size:11px;color:#596579;margin-top:8px}.admin{width:min(1200px,calc(100% - 30px));margin:auto;padding:35px 0}.sub{display:grid;grid-template-columns:280px 1fr;overflow:hidden;margin:14px 0}.proof{background:#e9eef2;min-height:270px}.proof img{width:100%;height:100%;object-fit:cover}.sm{padding:18px}.facts{display:flex;gap:12px;flex-wrap:wrap;font-size:11px;border-top:1px solid #e4e8ee;border-bottom:1px solid #e4e8ee;padding:9px 0}.review{display:grid;grid-template-columns:90px 1fr auto;gap:8px;align-items:end;margin-top:10px}.login{min-height:80vh;display:grid;place-items:center}.login .panel{width:min(410px,calc(100% - 30px));padding:28px}.login form{display:grid;gap:12px}@media(max-width:800px){.grid{grid-template-columns:1fr}.cards{grid-template-columns:repeat(2,1fr)}.sub{grid-template-columns:1fr}.review{grid-template-columns:1fr}}@media(max-width:520px){.fg,.checks,.cards{grid-template-columns:1fr}.wide{grid-column:auto}.nav{gap:8px;font-size:11px}.wrap,.admin{width:calc(100% - 20px)}}'''

def page(title,body,js=''):
 return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>{CSS}</style></head><body><header class="top"><a class="brand" href="/"><span class="mark">IEEE</span>FamilIEEEs</a><nav class="nav"><a href="/">Submit</a><a href="/media">Fam feed</a><a href="/admin">Admin</a></nav></header>{body}<script>{js}</script></body></html>'''

HOME='''<main class="wrap"><section class="hero"><span class="ey">IEEE AT UCLA · FAMILIEEES</span><h1>Flex your event.<br><span class="blue">Earn the points.</span></h1><p class="muted">Upload a proof photo, add the event location, and tell us what your FamilIEEE did.</p><div class="pills"><span>4+ members</span><span>1+ fam head</span><span>Advertised beforehand</span><span>Photo proof</span><span>Max 2/day</span><span>2+ miles apart</span></div></section><section class="grid"><div class="panel box"><span class="ey">EVENT SUBMISSION</span><h2>Send proof for review</h2><form id="form" class="fg"><label class="field"><span>FamilIEEE name *</span><input name="family_name" required></label><label class="field"><span>Your name *</span><input name="submitter_name" required></label><label class="field"><span>Event title *</span><input name="event_title" required></label><label class="field"><span>Event date *</span><input name="event_date" type="date" required></label><label class="field"><span>Event type</span><select name="event_type"><option value="social">FamilIEEE social / event</option><option value="clubwide">IEEE clubwide event</option><option value="quest">Quest</option><option value="competition">Competition</option><option value="other">Other</option></select></label><label class="field"><span>Number of fam members *</span><input name="member_count" type="number" min="0" max="100" value="4" required></label><label class="field wide"><span>Event location *</span><input name="location_text" required maxlength="300" placeholder="Royce Hall, UCLA or full street address"><small>Used to enforce the 2-mile same-day rule. Location lookup © OpenStreetMap contributors.</small></label><label class="field wide"><span>Brief description *</span><textarea name="description" required></textarea></label><div class="checks wide"><label class="check"><input type="checkbox" name="fam_head_present"> A fam head attended</label><label class="check"><input type="checkbox" name="advertised_beforehand"> Advertised beforehand</label></div><label class="upload wide">Proof photo *<br><input id="pic" type="file" accept="image/*" required><br><img id="prev" hidden></label><div class="wide"><p id="msg" class="msg"></p><button class="btn">Submit event →</button></div></form></div><aside class="panel box"><span class="ey">QUICK RULE CHECK</span><ol class="rules"><li>4+ fam members</li><li>At least 1 fam head</li><li>Advertised beforehand</li><li>Photo proof</li><li>Maximum 2 pending/approved events per fam per date</li><li>The second event must be at least 2 miles from the first</li></ol><span class="ey">LEADERBOARD</span><div id="leaders"></div></aside></section></main>'''
HOME_JS=r'''let photo=null,f=document.querySelector('#form'),msg=document.querySelector('#msg'),prev=document.querySelector('#prev');function M(t,c=''){msg.textContent=t;msg.className='msg '+c}document.querySelector('#pic').onchange=e=>{let x=e.target.files[0],r=new FileReader();if(!x)return;r.onload=()=>{let i=new Image();i.onload=()=>{let s=Math.min(1,1400/i.width),c=document.createElement('canvas');c.width=i.width*s;c.height=i.height*s;c.getContext('2d').drawImage(i,0,0,c.width,c.height);photo=c.toDataURL('image/jpeg',.78);prev.src=photo;prev.hidden=false};i.src=r.result};r.readAsDataURL(x)};f.onsubmit=async e=>{e.preventDefault();if(!photo)return M('Please upload a photo.','bad');let d=new FormData(f),p=Object.fromEntries(d);p.member_count=+p.member_count;p.fam_head_present=d.get('fam_head_present')==='on';p.advertised_beforehand=d.get('advertised_beforehand')==='on';p.photo_data=photo;M('Verifying location and submitting…');let r=await fetch('/api/submissions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)}),x=await r.json();if(!r.ok)return M(x.detail||'Submission failed','bad');f.reset();photo=null;prev.hidden=true;M('Submitted! Verified location: '+x.location_display,'ok');leaders()};async function leaders(){let r=await fetch('/api/leaderboard'),x=await r.json(),e=document.querySelector('#leaders');e.innerHTML=(x.leaderboard||[]).slice(0,8).map((a,i)=>`<div class="lr"><span>${i+1}</span><span>${a.family_name}</span><b>${a.points} pts</b></div>`).join('')||'<p class="msg">No approved events yet.</p>'}leaders();'''
MEDIA='''<main class="wrap"><section class="hero"><span class="ey">WHAT THE FAMS ARE UP TO</span><h1>FamilIEEE <span class="blue">Feed</span></h1><p class="muted">Approved events from across the FamilIEEEs community.</p></section><section class="toolbar panel"><select id="filter"><option value="">All FamilIEEEs</option></select><span id="count" class="msg">0 events shown</span></section><section id="cards" class="cards"></section><p style="text-align:center"><button id="more" class="btn" hidden>Load more</button></p></main>'''
MEDIA_JS=r'''let off=0,shown=0,g=document.querySelector('#cards'),f=document.querySelector('#filter'),more=document.querySelector('#more');function E(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function load(reset=false){if(reset){off=0;shown=0;g.innerHTML=''}let q=new URLSearchParams({limit:18,offset:off});if(f.value)q.set('family',f.value);let d=await (await fetch('/api/media?'+q)).json(),a=d.events||[];g.insertAdjacentHTML('beforeend',a.map(x=>`<article class="panel card"><div class="photo"><img loading="lazy" src="/api/media/${x.id}/photo"><span class="badge">${E(x.family_name)}</span></div><div class="cb"><div class="meta"><span>${x.event_date}</span><span>${E(x.event_type)}</span></div><h2>${E(x.event_title)}</h2><p class="muted">${E(x.description)}</p>${x.location_text?`<div class="loc">📍 ${E(x.location_text)}</div>`:''}<div class="foot"><span>${x.member_count} attendees</span><span class="pts">+${x.points_awarded} pts</span></div></div></article>`).join(''));if(!a.length&&!shown)g.innerHTML='<div class="panel box muted">No approved events yet.</div>';off=d.next_offset;shown+=a.length;document.querySelector('#count').textContent=shown+' events shown';more.hidden=!d.has_more}async function fams(){let d=await (await fetch('/api/leaderboard')).json();(d.leaderboard||[]).forEach(x=>{let o=document.createElement('option');o.value=o.textContent=x.family_name;f.appendChild(o)})}f.onchange=()=>load(true);more.onclick=()=>load();fams();load(true);'''
LOGIN='''<main class="login"><section class="panel"><span class="ey">ADMIN REVIEW</span><h1>Review event submissions</h1><form id="login"><label class="field"><span>Admin password</span><input id="pw" type="password" required></label><p id="lm" class="msg bad"></p><button class="btn">Open review queue →</button></form></section></main>'''
LOGIN_JS=r'''document.querySelector('#login').onsubmit=async e=>{e.preventDefault();let r=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:document.querySelector('#pw').value})});if(r.ok)location.href='/admin';else document.querySelector('#lm').textContent='Incorrect password'};'''
ADMIN='''<main class="admin"><section class="hero" style="padding-bottom:8px"><span class="ey">ADMIN DASHBOARD</span><h1 style="font-size:42px">Event review queue</h1></section><section class="toolbar panel"><div><button class="btn" data-s="pending">Pending</button> <button class="btn" data-s="approved">Approved</button> <button class="btn" data-s="denied">Denied</button> <button class="btn" data-s="all">All</button></div><input id="search" placeholder="Search family, event, location…"><button id="out" class="btn">Log out</button></section><section id="list"></section></main>'''
ADMIN_JS=r'''let all=[],st='pending',L=document.querySelector('#list');function E(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function pts(x){return x.event_type==='clubwide'?(x.member_count>=4&&x.fam_head_present?1:0):x.event_type==='social'?(x.member_count>=4&&x.fam_head_present&&x.advertised_beforehand?x.member_count:0):(x.points_awarded||0)}function draw(){let q=document.querySelector('#search').value.toLowerCase(),a=all.filter(x=>(st==='all'||x.status===st)&&(!q||(`${x.family_name} ${x.event_title} ${x.description} ${x.location_text||''}`).toLowerCase().includes(q)));L.innerHTML=a.map(x=>`<article class="panel sub"><div class="proof"><img src="${x.photo_data}"></div><div class="sm"><span class="ey">${E(x.family_name)} · ${x.status}</span><h2>${E(x.event_title)}</h2><p class="muted">${E(x.description)}</p><div class="facts"><b>${x.event_date}</b><span>${x.member_count} attendees</span><span>📍 ${E(x.location_text||'Legacy — no location')}</span></div><p class="msg ${x.location_text?'ok':'bad'}">${x.location_text?'✓ Location verified / daily-distance rule checked':'× No verified location'}</p><div class="review"><label class="field"><span>Points</span><input class="pi" type="number" value="${x.status==='approved'?x.points_awarded:pts(x)}"></label><label class="field"><span>Reviewer note</span><input class="ni" value="${E(x.reviewer_note||'')}"></label><div><button class="btn red act" data-st="denied" data-id="${x.id}">Deny</button> <button class="btn green act" data-st="approved" data-id="${x.id}">Approve</button></div></div></div></article>`).join('')||'<p class="msg">No submissions here.</p>';document.querySelectorAll('.act').forEach(b=>b.onclick=()=>review(b))}async function load(){let r=await fetch('/api/admin/submissions');if(r.status===401)return location.href='/admin/login';all=(await r.json()).submissions||[];draw()}async function review(b){let c=b.closest('.sub'),r=await fetch('/api/admin/submissions/'+b.dataset.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:b.dataset.st,points_awarded:+c.querySelector('.pi').value,reviewer_note:c.querySelector('.ni').value})});if(!r.ok)return alert((await r.json()).detail||'Could not save');load()}document.querySelectorAll('[data-s]').forEach(b=>b.onclick=()=>{st=b.dataset.s;draw()});document.querySelector('#search').oninput=draw;document.querySelector('#out').onclick=async()=>{await fetch('/api/admin/logout',{method:'POST'});location.href='/admin/login'};load();'''
